pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] calldata _tos, uint256[] calldata v) public {
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);
        // Ensure caddress has code that succeeds. Deploy a helper that accepts calls.
        // Without this, a fuzzed address without code makes low-level call always succeed, but we need to guarantee all calls succeed regardless of input.
        // Since the difference is about return value true vs false, and the reference always returns true, we just assert that.
        // We must ensure the transfer does not revert (e.g., from index out-of-bounds) and that the call succeeds.
        // To guarantee call succeeds even if _tos length > 0, we deploy a contract that accepts the call.
        Successor helper = new Successor();
        caddress = address(helper);
        // The reference always returns true; the mutant returns false
        bool ret = c.transfer(from, caddress, _tos, v);
        assertTrue(ret);
    }
}

contract Successor {
    fallback() external payable { }
}

