        assembly {
            let from_ptr := add(calldataload(4), 12) // load left-padded address, offset to last 20 bytes
            // if from == 0, revert
            if eq(from_ptr, 0) {
                revert(0, 0)
            }
        }
        // Otherwise succeed (do nothing)
    }
