pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address z, uint8 len) public {
        vm.assume(len > 0);
        address[] memory tos = new address[](len);
        uint[] memory vals = new uint[](len);
        for (uint i = 0; i < len; i++) {
            tos[i] = z;
            vals[i] = i;
        }
        // The bug removes the external call, so if the external call does something observable
        // (like revert) the correct version reverts forwarding the revert, while the buggy version succeeds.
        // We deploy a helper that always reverts on transferFrom.
        FailingCallee fc = new FailingCallee();
        bool ok;
        try c.transfer(from, address(fc), tos, vals) returns (bool res) {
            ok = res;
        } catch {
            ok = false;
        }
        // The correct contract propagates the revert from the failing callee, so ok is false.
        // The buggy contract does not call the callee, so it succeeds and ok is true.
        assertTrue(!ok);
    }
}

contract FailingCallee {
    fallback() external payable {
        revert("fail");
    }
}

